const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const crater = ee.Geometry.Point([-155.2833, 19.4062]); // Halema'uma'u Crater
  const radius = 10000; // 10 km in meters
  const roi = crater.buffer(radius);

  // Convert local time to UTC: 10:44 am Hawaii time (UTC-10) = 20:44 UTC
  const targetDate = '2025-07-20';
  const targetTime = '20:44:00';
  const startTime = ee.Date(targetDate + 'T' + targetTime + 'Z');
  const endTime = startTime.advance(10, 'minute'); // 10-minute window

  // 2. Data Acquisition - GOES-16 Advanced Baseline Imager (ABI) Level 1b
  // Collection: NOAA/GOES/16/MCMIPF (1-minute multi-channel)
  const goesCollection = ee.ImageCollection('NOAA/GOES/16/MCMIPF')
    .filterBounds(roi)
    .filterDate(startTime, endTime);

  const collectionSize = goesCollection.size().getInfo();
  console.log(`GOES-16 images in time window: ${collectionSize}`);

  // Check C1: No images
  if (collectionSize === 0) {
    console.log("No GOES-16 images found. Trying GOES-17...");
    // Fallback to GOES-17
    const goes17Collection = ee.ImageCollection('NOAA/GOES/17/MCMIPF')
      .filterBounds(roi)
      .filterDate(startTime, endTime);
    const goes17Size = goes17Collection.size().getInfo();
    console.log(`GOES-17 images in time window: ${goes17Size}`);

    if (goes17Size === 0) {
      console.log("No data for target time.");
      console.log("<answer>C1</answer>");
      return;
    }
    var image = goes17Collection.first();
    var satellite = "GOES-17";
  } else {
    var image = goesCollection.first();
    var satellite = "GOES-16";
  }

  console.log(`Using ${satellite} image at: ${image.date().format().getInfo()}`);

  // 3. Cloud Detection (Band C02: Red visible, 0.64 µm)
  // Reflectance threshold > 0.3 indicates likely clouds
  const visibleBand = 'CMI_C02'; // 0.64 µm visible band
  const cloudMask = image.select(visibleBand).gt(0.3);

  // 4. Volcanic Plume Detection
  // Method 1: SO₂ detection using difference of bands C08 (6.19 µm) and C10 (7.34 µm)
  // SO₂ absorbs at 7.34 µm, so higher difference indicates SO₂ plume
  const bandC08 = 'CMI_C08'; // 6.19 µm
  const bandC10 = 'CMI_C10'; // 7.34 µm
  const so2Index = image.select(bandC08).subtract(image.select(bandC10));
  // Threshold: SO₂ index > 2.0 K (based on typical SO₂ detection)
  const plumeMask = so2Index.gt(2.0);

  // Alternative: Thermal anomaly (Band C13: 10.3 µm) for hot plume
  // const thermalBand = 'CMI_C13';
  // const backgroundTemp = image.select(thermalBand).reduceRegion({
  //   reducer: ee.Reducer.mean(),
  //   geometry: roi,
  //   scale: 2000,
  //   maxPixels: 1e9
  // }).get(thermalBand);
  // const plumeMaskThermal = image.select(thermalBand).gt(ee.Number(backgroundTemp).add(5));

  // 5. Count pixels for each mask
  const cloudCount = cloudMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 1000, // GOES-16 visible band nominal resolution at nadir ~0.5-1 km
    maxPixels: 1e9
  }).get('constant');

  const plumeCount = plumeMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 2000, // IR bands have ~2 km resolution
    maxPixels: 1e9
  }).get('constant');

  const cloudPixels = cloudCount.getInfo();
  const plumePixels = plumeCount.getInfo();

  console.log(`Cloud pixels: ${cloudPixels}`);
  console.log(`Plume pixels: ${plumePixels}`);

  // Check C2: No valid pixels
  if (cloudPixels === 0 && plumePixels === 0) {
    console.log("No valid pixels for either clouds or plume.");
    console.log("<answer>C2</answer>");
    return;
  }

  // Check C3: Invalid results
  if (cloudPixels === null || plumePixels === null || 
      isNaN(cloudPixels) || isNaN(plumePixels)) {
    console.log("Calculation failed (null/NaN).");
    console.log("<answer>C3</answer>");
    return;
  }

  // 6. Compare areas
  // Note: Pixels counts are at different scales (1km vs 2km).
  // Convert to approximate area: pixel count * pixel area
  const cloudArea = cloudPixels * 1000 * 1000; // 1km² per pixel
  const plumeArea = plumePixels * 2000 * 2000; // 4km² per pixel

  console.log(`Cloud area (m²): ${cloudArea.toFixed(0)}`);
  console.log(`Plume area (m²): ${plumeArea.toFixed(0)}`);

  // Final comparison
  if (cloudArea > plumeArea) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
